/*
 * Held — lightweight 3D LED view on a 2D canvas (no WebGL / three.js, so the page stays small
 * enough to be served by the ESP32). Strips are circles whose radius follows from LED count and
 * density; units are millimetres; x right, y up, z toward the viewer.
 */
(function (root) {
	'use strict';

	const DEG = Math.PI / 180;
	const SHELL = { rx: 250, ry: 375, rz: 230 };   // ~500 x 750 mm heart, as an ellipsoid envelope
	const FOV = 38 * DEG;

	class HeldView3D {
		constructor(canvas) {
			this.cv = canvas;
			this.ctx = canvas.getContext('2d');
			this.yaw = -25 * DEG;
			this.pitch = 12 * DEG;
			this.dist = 2100;
			this.autoRotate = true;
			this.glow = true;
			this.shell = true;
			this.strips = [];       // [{ pos: Float32Array(3n), origin }]
			this.onPick = null;     // (strip, led) => void
			this._proj = [];
			this._bindPointer();
		}

		resetView() { this.yaw = 0; this.pitch = 0; this.dist = 2100; }

		// strips: schema strip objects (leds, density, startAngle, ccw, yaw, pitch, cy, origin)
		setStrips(strips) {
			this.strips = strips.map((s) => {
				const n = s.leds;
				const r = (n / s.density) * 1000 / (2 * Math.PI);
				const dir = s.ccw ? 1 : -1;
				const cyw = Math.cos(s.yaw * DEG), syw = Math.sin(s.yaw * DEG);
				const cp = Math.cos(s.pitch * DEG), sp = Math.sin(s.pitch * DEG);
				const pos = new Float32Array(3 * n);
				for (let i = 0; i < n; i++) {
					const a = (s.startAngle + dir * 360 * i / n) * DEG;
					let x = r * Math.cos(a), y = r * Math.sin(a), z = 0;
					const y1 = y * cp - z * sp, z1 = y * sp + z * cp;       // pitch about x
					const x2 = x * cyw + z1 * syw, z2 = -x * syw + z1 * cyw; // yaw about y
					pos[3 * i] = x2; pos[3 * i + 1] = y1 + s.cy; pos[3 * i + 2] = z2;
				}
				// one marker where each pattern copy starts from the origin (every other copy when mirrored)
				const origins = [], V = n / s.reps, step = s.mirror ? 2 * V : V;
				for (let d = 0; d < n - 1e-6; d += step) origins.push(Math.round(s.origin + d) % Math.max(1, n));
				return { pos: pos, n: n, origins: origins };
			});
		}

		_bindPointer() {
			const cv = this.cv, pts = new Map();
			let moved = 0, pinch0 = 0, dist0 = 0;
			cv.addEventListener('pointerdown', (e) => {
				cv.setPointerCapture(e.pointerId);
				pts.set(e.pointerId, { x: e.clientX, y: e.clientY });
				moved = 0;
				if (pts.size === 2) { const p = [...pts.values()]; pinch0 = Math.hypot(p[0].x - p[1].x, p[0].y - p[1].y); dist0 = this.dist; }
			});
			cv.addEventListener('pointermove', (e) => {
				const prev = pts.get(e.pointerId);
				if (!prev) return;
				const dx = e.clientX - prev.x, dy = e.clientY - prev.y;
				prev.x = e.clientX; prev.y = e.clientY;
				moved += Math.abs(dx) + Math.abs(dy);
				if (pts.size === 1) {
					this.yaw += dx * 0.008;
					this.pitch = Math.max(-1.4, Math.min(1.4, this.pitch + dy * 0.008));
					if (moved > 4 && this.autoRotate) { this.autoRotate = false; this._emit('rotate'); }
				} else if (pts.size === 2 && pinch0 > 0) {
					const p = [...pts.values()];
					this.dist = Math.max(700, Math.min(5000, dist0 * pinch0 / Math.max(10, Math.hypot(p[0].x - p[1].x, p[0].y - p[1].y))));
				}
			});
			const up = (e) => {
				if (pts.size === 1 && moved < 6) this._pick(e);
				pts.delete(e.pointerId);
				if (pts.size < 2) pinch0 = 0;
			};
			cv.addEventListener('pointerup', up);
			cv.addEventListener('pointercancel', (e) => pts.delete(e.pointerId));
			cv.addEventListener('wheel', (e) => {
				e.preventDefault();
				this.dist = Math.max(700, Math.min(5000, this.dist * Math.exp(e.deltaY * 0.001)));
			}, { passive: false });
		}

		_emit(what) { if (this.onChange) this.onChange(what); }

		_pick(e) {
			const rect = this.cv.getBoundingClientRect();
			const k = this.cv.width / rect.width;
			const mx = (e.clientX - rect.left) * k, my = (e.clientY - rect.top) * k;
			let best = null, bd = (18 * k) * (18 * k);
			for (const p of this._proj) {
				const d = (p.x - mx) * (p.x - mx) + (p.y - my) * (p.y - my);
				if (d < bd) { bd = d; best = p; }
			}
			if (this.onPick) this.onPick(best ? best.s : -1, best ? best.i : -1);
		}

		_resize() {
			const r = this.cv.getBoundingClientRect();
			const dpr = Math.min(2, window.devicePixelRatio || 1);
			const w = Math.max(50, Math.round(r.width * dpr)), h = Math.max(50, Math.round(r.height * dpr));
			if (this.cv.width !== w || this.cv.height !== h) { this.cv.width = w; this.cv.height = h; }
		}

		// colors: array per strip of Float32/64Array(3n) 0..1; gain: display brightness factor
		draw(colors, gain, dt) {
			this._resize();
			if (this.autoRotate) this.yaw += (dt || 0) * 0.15;
			const ctx = this.ctx, W = this.cv.width, H = this.cv.height;
			const f = Math.min(W, H) / (2 * Math.tan(FOV / 2));
			const cy = Math.cos(this.yaw), sy = Math.sin(this.yaw), cp = Math.cos(this.pitch), sp = Math.sin(this.pitch);
			const dist = this.dist;
			const proj = (x, y, z, o) => {
				const x1 = x * cy + z * sy, z1 = -x * sy + z * cy;
				const y2 = y * cp - z1 * sp, z2 = y * sp + z1 * cp;
				const zc = dist - z2;
				o.x = W / 2 + f * x1 / zc; o.y = H / 2 - f * y2 / zc; o.z = zc; o.k = f / zc;
				return o;
			};
			ctx.globalCompositeOperation = 'source-over';
			ctx.clearRect(0, 0, W, H);

			const tmp = { x: 0, y: 0, z: 0, k: 0 };
			if (this.shell) {
				ctx.strokeStyle = 'rgba(160, 90, 70, 0.13)';
				ctx.lineWidth = 1;
				for (let lat = -60; lat <= 60; lat += 30) {
					ctx.beginPath();
					for (let a = 0; a <= 360; a += 10) {
						const c = Math.cos(lat * DEG);
						proj(SHELL.rx * c * Math.cos(a * DEG), SHELL.ry * Math.sin(lat * DEG), SHELL.rz * c * Math.sin(a * DEG), tmp);
						a ? ctx.lineTo(tmp.x, tmp.y) : ctx.moveTo(tmp.x, tmp.y);
					}
					ctx.stroke();
				}
				for (let lon = 0; lon < 180; lon += 30) {
					ctx.beginPath();
					for (let a = 0; a <= 360; a += 10) {
						const c = Math.cos(a * DEG);
						proj(SHELL.rx * c * Math.cos(lon * DEG), SHELL.ry * Math.sin(a * DEG), SHELL.rz * c * Math.sin(lon * DEG), tmp);
						a ? ctx.lineTo(tmp.x, tmp.y) : ctx.moveTo(tmp.x, tmp.y);
					}
					ctx.stroke();
				}
			}

			// project + depth sort all LEDs
			const list = this._proj;
			list.length = 0;
			for (let s = 0; s < this.strips.length; s++) {
				const st = this.strips[s], col = colors[s];
				for (let i = 0; i < st.n; i++) {
					const o = proj(st.pos[3 * i], st.pos[3 * i + 1], st.pos[3 * i + 2], {});
					o.s = s; o.i = i;
					o.r = col ? col[3 * i] * gain : 0; o.g = col ? col[3 * i + 1] * gain : 0; o.b = col ? col[3 * i + 2] * gain : 0;
					list.push(o);
				}
			}
			list.sort((a, b) => b.z - a.z);

			const ledR = Math.max(1.2, 5.5 * f / dist);
			// dark LED bodies so unlit pixels and the strip path stay visible
			ctx.fillStyle = '#2a1a16';
			for (const o of list) { ctx.beginPath(); ctx.arc(o.x, o.y, ledR * 0.8 * o.k * dist / f, 0, 2 * Math.PI); ctx.fill(); }

			ctx.globalCompositeOperation = 'lighter';
			for (const o of list) {
				const m = Math.max(o.r, o.g, o.b);
				if (m < 0.01) continue;
				const sc = o.k * dist / f;
				const R = Math.round(Math.min(1, o.r) * 255), G = Math.round(Math.min(1, o.g) * 255), B = Math.round(Math.min(1, o.b) * 255);
				if (this.glow) {
					ctx.fillStyle = `rgba(${R},${G},${B},${0.05 + 0.05 * m})`;
					ctx.beginPath(); ctx.arc(o.x, o.y, ledR * 7 * sc, 0, 2 * Math.PI); ctx.fill();
					ctx.fillStyle = `rgba(${R},${G},${B},${0.25 * m})`;
					ctx.beginPath(); ctx.arc(o.x, o.y, ledR * 2.6 * sc, 0, 2 * Math.PI); ctx.fill();
				}
				ctx.fillStyle = `rgb(${R},${G},${B})`;
				ctx.beginPath(); ctx.arc(o.x, o.y, ledR * sc, 0, 2 * Math.PI); ctx.fill();
			}

			// origin markers
			ctx.globalCompositeOperation = 'source-over';
			ctx.strokeStyle = 'rgba(255, 210, 140, 0.8)';
			ctx.lineWidth = Math.max(1, f / dist * 1.2);
			for (const st of this.strips) {
				for (const i of st.origins) {
					if (i >= st.n) continue;
					proj(st.pos[3 * i], st.pos[3 * i + 1], st.pos[3 * i + 2], tmp);
					ctx.beginPath(); ctx.arc(tmp.x, tmp.y, ledR * 2.4 * tmp.k * dist / f, 0, 2 * Math.PI); ctx.stroke();
				}
			}
			if (this.highlight) {
				const st = this.strips[this.highlight.s];
				if (st && this.highlight.i < st.n) {
					const i = this.highlight.i;
					proj(st.pos[3 * i], st.pos[3 * i + 1], st.pos[3 * i + 2], tmp);
					ctx.strokeStyle = '#7fd0ff';
					ctx.beginPath(); ctx.arc(tmp.x, tmp.y, ledR * 3 * tmp.k * dist / f, 0, 2 * Math.PI); ctx.stroke();
				}
			}
		}
	}

	// Space-time strip: each frame is one row (all strips side by side), newest at the top.
	class HeldKymo {
		constructor(canvas) {
			this.cv = canvas;
			this.ctx = canvas.getContext('2d');
			this.cv.height = 110;
		}
		push(colors, gain) {
			let total = 0;
			for (const c of colors) total += (c ? c.length / 3 : 0) + 2;
			total = Math.max(1, total - 2);
			const cv = this.cv, ctx = this.ctx;
			if (cv.width !== total) { cv.width = total; ctx.fillStyle = '#000'; ctx.fillRect(0, 0, cv.width, cv.height); }
			ctx.drawImage(cv, 0, 0, cv.width, cv.height - 1, 0, 1, cv.width, cv.height - 1);
			const row = ctx.createImageData(cv.width, 1), d = row.data;
			let x = 0;
			for (const c of colors) {
				if (!c) continue;
				for (let i = 0; i < c.length / 3; i++, x++) {
					d[4 * x] = Math.min(255, c[3 * i] * gain * 255);
					d[4 * x + 1] = Math.min(255, c[3 * i + 1] * gain * 255);
					d[4 * x + 2] = Math.min(255, c[3 * i + 2] * gain * 255);
					d[4 * x + 3] = 255;
				}
				for (let g = 0; g < 2 && x < cv.width; g++, x++) { d[4 * x] = 60; d[4 * x + 1] = 60; d[4 * x + 2] = 60; d[4 * x + 3] = 255; }
			}
			ctx.putImageData(row, 0, 0);
		}
	}

	root.HeldView3D = HeldView3D;
	root.HeldKymo = HeldKymo;
})(window);
